import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    static class NamedFactory implements ThreadFactory {
        private final String prefix;
        private final AtomicInteger seq = new AtomicInteger(1);
        NamedFactory(String prefix) { this.prefix = prefix; }
        public Thread newThread(Runnable r) { return new Thread(r, prefix + "-" + seq.getAndIncrement()); }
    }

    public static void main(String[] args) throws Exception {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                2, 4, 60L, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(3), new NamedFactory("order"),
                new ThreadPoolExecutor.AbortPolicy());
        System.out.println("core=" + pool.getCorePoolSize() + ", max=" + pool.getMaximumPoolSize() + ", queueCapacity=3");

        CountDownLatch release = new CountDownLatch(1);
        Runnable block = () -> {
            try { release.await(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        };
        for (int i = 0; i < 7; i++) pool.execute(block);
        Thread.sleep(300L);

        System.out.println("running workers (core+extra) = " + pool.getPoolSize());
        System.out.println("queued tasks                 = " + pool.getQueue().size());
        System.out.println("active workers               = " + pool.getActiveCount());
        System.out.println("largest pool size            = " + pool.getLargestPoolSize());

        try {
            pool.execute(block);
            System.out.println("8th task                     = accepted");
        } catch (RejectedExecutionException e) {
            System.out.println("8th task                     = rejected by AbortPolicy");
        }

        release.countDown();
        pool.shutdown();
        System.out.println("terminated within 5s         = " + pool.awaitTermination(5, TimeUnit.SECONDS));
        System.out.println("completed tasks              = " + pool.getCompletedTaskCount());
    }
}
